function reviewProfileMethodCount(tutorials){
 const active=tutorials.filter(t=>!t.archived),origins=new Set(active.filter(t=>t.sourceOrigin).map(t=>JSON.stringify([t.sourceOrigin.nodeId,t.sourceOrigin.methodId]))),identities=new Set(active.map(t=>t.id));let localOnly=0;
 for(const n of S.nodes)for(const m of n.methods.filter(m=>m.author===S.user.name))if(!origins.has(JSON.stringify([n.id,m.id]))&&!(m.serviceReference?.authorId===S.user.id&&identities.has(m.serviceReference.id)))localOnly++;
 return {total:active.length+localOnly,localOnly,active,archived:tutorials.length-active.length};
}
function reviewProfileMethodStat(){return '<div class="num" id="profile-method-total">核对中</div><span class="muted small">我的方法</span>'}
function reviewProfileMethodsSummary(){queueMicrotask(()=>reviewReadProfileMethods());return `<section class="box" id="profile-method-summary" style="margin:18px 0"><div class="row between"><h2>我的服务教程</h2><div class="row">${btn('服务教程与历史','review-owned-visible','ghost')}${btn('服务实践与历史','review-owned-practices','ghost')}</div></div><p id="profile-method-status" class="small muted" role="status">正在核对本人教程…</p><div id="profile-method-content"></div><button id="profile-method-refresh" class="ghost">重新读取教程</button></section>`}
async function reviewReadProfileMethods(force=false){
 const host=document.getElementById('profile-method-summary'),total=document.getElementById('profile-method-total');if(!host||!total||reviewAuthBusy||reviewAccountConnecting||!S.user?.reviewService||!force&&(host.dataset.reading==='true'||host.dataset.loaded==='true'))return;const generation=String(Number(host.dataset.generation||0)+1);host.dataset.generation=generation;host.dataset.reading='true';const context=reviewContext(),status=host.querySelector('#profile-method-status'),content=host.querySelector('#profile-method-content'),refresh=host.querySelector('#profile-method-refresh');refresh.onclick=()=>reviewReadProfileMethods(true);status.textContent='正在核对本人教程…';total.textContent='核对中';content.innerHTML='';
 try{const r=await reviewKnowledgeRequest('/api/review-owned-tutorials',{context});if(!host.isConnected||!total.isConnected||!reviewContextCurrent(context)||host.dataset.generation!==generation)return;if(r.ownerId!==context.ownerId||!Array.isArray(r.tutorials)||r.tutorials.some(t=>t.authorId!==context.ownerId))throw Error('本人教程回执不一致。');const count=reviewProfileMethodCount(r.tutorials);total.textContent=String(count.total);host.dataset.loaded='true';status.textContent=`服务当前保存 ${count.active.length} 份教程，已归档 ${count.archived} 份；行动档案中另有 ${count.localOnly} 份方法。相同来源不重复计数。`;content.innerHTML=count.active.length?`<details class="saved-notes"><summary>查看当前教程（${count.active.length} 份）</summary>${count.active.map(t=>`<article class="list-row"><h3>${esc(t.title)}</h3><p class="small muted">${t.visibility==='public'?'原保存范围：公开':'私人保存'} · 教程 ${esc(t.version.slice(0,8))}</p></article>`).join('')}</details>`:'<p class="small muted">本人尚无当前服务教程，已归档内容可在历史中查看。</p>';
 }catch(e){if(host.isConnected&&reviewContextCurrent(context)&&host.dataset.generation===generation){host.dataset.loaded='false';total.textContent='待核对';status.textContent=reviewOwnProfileError(e)}}finally{if(host.dataset.generation===generation)host.dataset.reading='false'}
}
